<?php require 'functions.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$id]);$cat=$s->fetch();if(!$cat){http_response_code(404);exit('Kategori tidak ditemukan');}$s=$pdo->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.category_id=? ORDER BY p.created_at DESC');$s->execute([$id]);$products=$s->fetchAll();$pageTitle=$cat['name'];require 'header.php';?><style>.product-seller-byline{display:block;color:#876d53;font-size:11px;margin:3px 0 7px;line-height:1.4}</style><section class="section"><div class="section-head"><h2><?=e($cat['name'])?></h2></div><div class="products"><?php foreach($products as $p):?><article class="product"><a href="<?=url('product.php?id='.$p['id'])?>"><img src="<?=e(image_url($p['image']))?>"></a><div class="product-info"><a class="product-name" href="<?=url('product.php?id='.$p['id'])?>"><?=e($p['name'])?></a><small class="product-seller-byline">Dijual oleh <?=e(product_seller_label($pdo,(int)($p['seller_id']??0)))?></small><b><?=rupiah($p['price'])?></b></div></article><?php endforeach;?></div></section><?php require 'footer.php';?>